  !< @{
  !< \brief BLAS Level 1 API
  !< 
  !< \details
  !<  amaxStridedBatched finds the first index of the element of maximum magnitude of each vector x_i in a batch, for i = 1, ..., batchCount.
  !< 
  !< - Supported precisions in rocBLAS : s,d,c,z
  !< - Supported precisions in cuBLAS  : No support
  !< 
  !< @param[in]
  !< handle    [hipblasHandle_t]
  !<           handle to the hipblas library context queue.
  !< @param[in]
  !< n         [int]
  !<           number of elements in each vector x_i
  !< @param[in]
  !< x         device pointer to the first vector x_1.
  !< @param[in]
  !< incx      [int]
  !<           specifies the increment for the elements of each x_i. incx must be > 0.
  !< @param[in]
  !< stridex   [hipblasStride]
  !<           specifies the pointer increment between one x_i and the next x_(i + 1).
  !< @param[in]
  !< batchCount [int]
  !<           number of instances in the batch
  !< @param[out]
  !< result
  !<           device or host pointer for storing contiguous batchCount results.
  !<           return is 0 if n <= 0, incx<=0.
  !< 
  !<  ******************************************************************
  interface hipblasIsamaxStridedBatched
    function hipblasIsamaxStridedBatched_(handle,n,x,incx,stridex,batchCount,result) bind(c, name="hipblasIsamaxStridedBatched")
      use iso_c_binding
      use hipfort_hipblas.h
      use hipfort_hip_runtime.h

      implicit none
      type(c_ptr), value :: handle
      integer(kind=c_int), value :: n
      type(c_ptr), value :: x
      integer(kind=c_int), value :: incx
      integer(kind=c_long), value :: stridex
      integer(kind=c_int), value :: batchCount
      type(c_ptr), value :: result
      integer(kind(hipblasStatus_t)) :: hipblasIsamaxStridedBatched
    end function

  end interface



