  !< dotc  performs the dot product of the conjugate of complex vector x and complex vector y
  !< 
  !<     result = conjugate (x) * y;
  !< 
  !< - Supported precisions in rocBLAS : h,bf,s,d,c,z
  !< - Supported precisions in cuBLAS  : s,d,c,z
