  !< 
  !< \details
  !< dotStridedBatched(u)  performs a batch of dot products of vectors x and y
  !< 
  !<     result_i = x_i * y_i;
  !< 
  !< dotcStridedBatched  performs a batch of dot products of the conjugate of complex vector x and complex vector y
  !< 
  !<     result_i = conjugate (x_i) * y_i;
  !< 
  !< where (x_i, y_i) is the i-th instance of the batch.
  !< x_i and y_i are vectors, for i = 1, ..., batchCount
  !< 
  !< - Supported precisions in rocBLAS : h,bf,s,d,c,z
  !< - Supported precisions in cuBLAS  : No support
  !< 
  !< @param[in]
  !< handle    [hipblasHandle_t]
  !<           handle to the hipblas library context queue.
  !< @param[in]
  !< n         [int]
  !<           the number of elements in each x_i and y_i.
  !< @param[in]
  !< x         device pointer to the first vector (x_1) in the batch.
  !< @param[in]
  !< incx      [int]
  !<           specifies the increment for the elements of each x_i.
  !< @param[in]
  !< stridex     [hipblasStride]
  !<             stride from the start of one vector (x_i) and the next one (x_i+1)
  !< @param[in]
  !< y         device pointer to the first vector (y_1) in the batch.
  !< @param[in]
  !< incy      [int]
  !<           specifies the increment for the elements of each y_i.
  !< @param[in]
  !< stridey     [hipblasStride]
  !<             stride from the start of one vector (y_i) and the next one (y_i+1)
  !< @param[in]
  !< batchCount [int]
  !<             number of instances in the batch
  !< @param[inout]
  !< result
  !<           device array or host array of batchCount size to store the dot products of each batch.
  !<           return 0.0 for each element if n <= 0.
  !< 
  !<  ******************************************************************
  interface hipblasHdotStridedBatched
    function hipblasHdotStridedBatched_(handle,n,x,incx,stridex,y,incy,stridey,batchCount,result) bind(c, name="hipblasHdotStridedBatched")
      use iso_c_binding
      use hipfort_hipblas.h
      use hipfort_hip_runtime.h

      implicit none
      type(c_ptr), value :: handle
      integer(kind=c_int), value :: n
      type(c_ptr), value :: x
      integer(kind=c_int), value :: incx
      integer(kind=c_long), value :: stridex
      type(c_ptr), value :: y
      integer(kind=c_int), value :: incy
      integer(kind=c_long), value :: stridey
      integer(kind=c_int), value :: batchCount
      type(c_ptr), value :: result
      integer(kind(hipblasStatus_t)) :: hipblasHdotStridedBatched
    end function

