  !< @{
  !< \brief BLAS Level 1 API
  !< 
  !< \details
  !< nrm2 computes the euclidean norm of a real or complex vector
  !< 
  !<           result := sqrt( x'*x ) for real vectors
  !<           result := sqrt( x**H*x ) for complex vectors
  !< 
  !< - Supported precisions in rocBLAS : s,d,c,z,sc,dz
  !< - Supported precisions in cuBLAS  : s,d,sc,dz
  !< 
  !< @param[in]
  !< handle    [hipblasHandle_t]
  !<           handle to the hipblas library context queue.
  !< @param[in]
  !< n         [int]
  !<           the number of elements in x.
  !< @param[in]
  !< x         device pointer storing vector x.
  !< @param[in]
  !< incx      [int]
  !<           specifies the increment for the elements of y.
  !< @param[inout]
  !< result
  !<           device pointer or host pointer to store the nrm2 product.
  !<           return is 0.0 if n, incx<=0.
  !<  ******************************************************************
  interface hipblasSnrm2
    function hipblasSnrm2_(handle,n,x,incx,result) bind(c, name="hipblasSnrm2")
      use iso_c_binding
      use hipfort_hipblas.h
      use hipfort_hip_runtime.h

      implicit none
      type(c_ptr), value :: handle
      integer(kind=c_int), value :: n
      type(c_ptr), value :: x
      integer(kind=c_int), value :: incx
      type(c_ptr), value :: result
      integer(kind(hipblasStatus_t)) :: hipblasSnrm2
    end function

  end interface



