  !< @{
  !< \brief BLAS Level 1 API
  !< 
  !< \details
  !< nrm2StridedBatched computes the euclidean norm over a batch of real or complex vectors
  !< 
  !<           := sqrt( x_i'*x_i ) for real vectors x, for i = 1, ..., batchCount
  !<           := sqrt( x_i**H*x_i ) for complex vectors, for i = 1, ..., batchCount
  !< 
  !< - Supported precisions in rocBLAS : s,d,c,z,sc,dz
  !< - Supported precisions in cuBLAS  : No support
  !< 
  !< @param[in]
  !< handle    [hipblasHandle_t]
  !<           handle to the hipblas library context queue.
  !< @param[in]
  !< n         [int]
  !<           number of elements in each x_i.
  !< @param[in]
  !< x         device pointer to the first vector x_1.
  !< @param[in]
  !< incx      [int]
  !<           specifies the increment for the elements of each x_i. incx must be > 0.
  !< @param[in]
  !< stridex   [hipblasStride]
  !<           stride from the start of one vector (x_i) and the next one (x_i+1).
  !<           There are no restrictions placed on stride_x, however the user should
  !<           take care to ensure that stride_x is of appropriate size, for a typical
  !<           case this means stride_x >= n * incx.
  !< @param[in]
  !< batchCount [int]
  !<           number of instances in the batch
  !< @param[out]
  !< result
  !<           device pointer or host pointer to array for storing contiguous batchCount results.
  !<           return is 0.0 for each element if n <= 0, incx<=0.
  !< 
  !<  ******************************************************************
  interface hipblasSnrm2StridedBatched
    function hipblasSnrm2StridedBatched_(handle,n,x,incx,stridex,batchCount,result) bind(c, name="hipblasSnrm2StridedBatched")
      use iso_c_binding
      use hipfort_hipblas.h
      use hipfort_hip_runtime.h

      implicit none
      type(c_ptr), value :: handle
      integer(kind=c_int), value :: n
      type(c_ptr), value :: x
      integer(kind=c_int), value :: incx
      integer(kind=c_long), value :: stridex
      integer(kind=c_int), value :: batchCount
      type(c_ptr), value :: result
      integer(kind(hipblasStatus_t)) :: hipblasSnrm2StridedBatched
    end function

  end interface



