      type(c_ptr), value :: a
      integer(kind=c_long), value :: stridea
      type(c_ptr), value :: b
      integer(kind=c_long), value :: strideb
      type(c_ptr), value :: c
      integer(kind=c_long), value :: stridec
      type(c_ptr), value :: s
      integer(kind=c_long), value :: strides
      integer(kind=c_int), value :: batchCount
      integer(kind(hipblasStatus_t)) :: hipblasSrotgStridedBatched
    end function

