      type(c_ptr), value :: x
      integer(kind=c_int), value :: incx
      type(c_ptr), value :: y
      integer(kind=c_int), value :: incy
      type(c_ptr), value :: AP
      integer(kind=c_int), value :: lda
      integer(kind(hipblasStatus_t)) :: hipblasSger
    end function

  end interface



