      use hipfort_hip_runtime.h

      implicit none
      integer(kind=c_int), value :: lightHandle
      integer(kind=c_int), value :: transformDesc
      type(c_ptr), value :: alpha
      type(c_ptr), value :: A
      integer(kind=c_int), value :: Adesc
      type(c_ptr), value :: beta
      type(c_ptr), value :: B
      integer(kind=c_int), value :: Bdesc
      type(c_ptr), value :: C
      integer(kind=c_int), value :: Cdesc
      integer(kind=c_int), value :: stream
      integer(kind(hipblasStatus_t)) :: hipblasLtMatrixTransform
    end function

  end interface

